package org.sormus.downloads;
import android.app.*;import android.widget.Toast;import android.os.*;import android.content.*;import android.net.Uri;import android.database.Cursor;import android.provider.OpenableColumns;import org.json.*;import java.io.*;import java.net.*;import java.util.*;
public final class TransferService extends Service {
 static volatile boolean running=false;private static final int ID=71;private NotificationManager manager;private volatile boolean stopped=false;private volatile HttpURLConnection connection;private Thread worker;private long lastNotice=0;private final Handler main=new Handler(Looper.getMainLooper());private final TransferInbox<Batch> inbox=new TransferInbox<>(8);private int latestStartId;private boolean destroyed;
 private static final class Batch {final ArrayList<Uri> files;final String link,server,token;Batch(ArrayList<Uri> files,String link,String server,String token){this.files=files;this.link=link;this.server=server;this.token=token;}}

 @Override public void onCreate(){super.onCreate();manager=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);manager.createNotificationChannel(new NotificationChannel("transfers","File transfers",NotificationManager.IMPORTANCE_LOW));}
 private Notification notification(String text,boolean ongoing){Notification.Builder builder=new Notification.Builder(this,"transfers").setSmallIcon(android.R.drawable.stat_sys_upload).setContentTitle("Sormus Downloads").setContentText(text).setStyle(new Notification.BigTextStyle().bigText(text)).setOngoing(ongoing).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,DownloadsActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT));if(ongoing)builder.addAction(new Notification.Action.Builder(android.R.drawable.ic_menu_close_clear_cancel,"Cancel",PendingIntent.getService(this,1,new Intent(this,TransferService.class).setAction("cancel"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT)).build());return builder.build();}
 private void progress(String s){if(System.currentTimeMillis()-lastNotice>600){lastNotice=System.currentTimeMillis();manager.notify(ID,notification(s,true));}}
 @Override public int onStartCommand(Intent intent,int flags,int startId){latestStartId=startId;if(intent==null){if(worker==null)stopSelfResult(startId);return START_NOT_STICKY;}if("cancel".equals(intent.getAction())){stopped=true;inbox.clear();if(connection!=null)connection.disconnect();if(worker!=null)worker.interrupt();else finishBatch("Cancelled. Check recent transfers before sending again.");return START_NOT_STICKY;}if((flags&(START_FLAG_REDELIVERY|START_FLAG_RETRY))!=0){Toast.makeText(this,"Transfer was interrupted. Check recent transfers before sharing again.",Toast.LENGTH_LONG).show();if(worker==null)stopSelfResult(startId);return START_NOT_STICKY;}if(stopped){Toast.makeText(this,"Cancelling the current transfers. Share again after cancellation finishes.",Toast.LENGTH_LONG).show();if(worker==null)stopSelfResult(startId);return START_NOT_STICKY;}
  try{ArrayList<Uri> files=intent.getParcelableArrayListExtra("files");if(files==null)files=new ArrayList<>();String link=intent.getStringExtra("link");if(link==null)link="";String id=intent.getStringExtra("batchId");if(id==null||!id.matches("[a-f0-9-]{36}")||files.size()>20||files.isEmpty()&&!TransferProtocol.link(link)||!link.isEmpty()&&!TransferProtocol.link(link))throw new Exception("Invalid shared transfer.");for(Uri uri:files)if(uri==null||!"content".equals(uri.getScheme()))throw new Exception("Choose files through Android's picker.");if(inbox.seen(id)){if(worker==null&&inbox.isEmpty())stopSelfResult(startId);return START_NOT_STICKY;}DownloadsApi api=new DownloadsApi(this);String server=TransferProtocol.server(api.preferences.getString("server","")),token=api.preferences.getString("token","");if(!token.matches("[a-f0-9]{64}"))throw new Exception("Pair this phone first.");if(!inbox.offer(id,new Batch(new ArrayList<>(files),link,server,token)))throw new Exception("The transfer queue is full. Share this selection again after an upload finishes.");running=true;startForeground(ID,notification(worker==null?"Preparing transfer":"Transfer queued",true));if(worker==null)startNext();}catch(Exception e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();if(worker==null)stopSelfResult(startId);}return START_NOT_STICKY;}
 private void startNext(){final Batch batch=inbox.poll();if(batch==null){finishBatch("Transfers finished. Open Downloads for receipts.");return;}lastNotice=0;worker=new Thread(()->{String result="Sent to PC. Open the app for transfer receipts.";try{DownloadsApi api=new DownloadsApi(this,batch.server,batch.token);JSONObject status=api.json("GET","/api/file-downloads/native/status",null);if(!status.optBoolean("available"))throw new Exception(status.optString("reason","Downloads is unavailable."));long limit=status.getLong("maxFileBytes");for(Uri uri:batch.files){if(stopped)throw new InterruptedException();upload(api,uri,limit,status.optBoolean("torrentsEnabled"));}if(!batch.link.isEmpty()){if(stopped)throw new InterruptedException();api.json("POST","/api/file-downloads/native/jobs",new JSONObject().put("requestId",UUID.randomUUID().toString()).put("kind","link").put("url",batch.link));result="Torrent sent to PC. Check qBittorrent and the app receipts.";}}catch(Exception e){result=(stopped?"Cancelled.":"Transfer stopped: "+e.getMessage())+" Check recent transfers before sending again.";}final String outcome=result;main.post(()->{if(destroyed)return;worker=null;if(!stopped&&!inbox.isEmpty())startNext();else finishBatch(outcome);});},"sormus-file-transfer");worker.start();}
 private void finishBatch(String result){running=false;stopForeground(STOP_FOREGROUND_REMOVE);manager.notify(ID,notification(result,false));stopSelfResult(latestStartId);}
 @Override public void onTimeout(int startId,int type){stopped=true;inbox.clear();if(connection!=null)connection.disconnect();if(worker!=null)worker.interrupt();finishBatch("Android stopped the transfer. Check recent transfers before sending again.");stopSelf();}
 private void upload(DownloadsApi api,Uri uri,long limit,boolean torrents)throws Exception{if(!"content".equals(uri.getScheme()))throw new Exception("Choose a file through Android's file picker.");String name="upload.bin";long size=-1;try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE},null,null,null)){if(c!=null&&c.moveToFirst()){int n=c.getColumnIndex(OpenableColumns.DISPLAY_NAME),s=c.getColumnIndex(OpenableColumns.SIZE);if(n>=0&&!c.isNull(n))name=c.getString(n);if(s>=0&&!c.isNull(s))size=c.getLong(s);}}File cached=null;try{if(size<0){cached=File.createTempFile("upload-",".part",getCacheDir());try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(cached)){size=copy(in,out,limit,null);}}if(size>limit)throw new Exception("File exceeds the PC upload limit.");if(stopped||Thread.currentThread().isInterrupted())throw new InterruptedException();JSONObject job=api.json("POST","/api/file-downloads/native/jobs",new JSONObject().put("requestId",UUID.randomUUID().toString()).put("name",name).put("size",size).put("kind",torrents&&name.toLowerCase(Locale.ROOT).endsWith(".torrent")?"torrent":"file"));String id=job.getString("id");if(stopped||Thread.currentThread().isInterrupted())throw new InterruptedException();connection=api.connection("PUT","/api/file-downloads/native/jobs/"+id+"/content");connection.setDoOutput(true);connection.setRequestProperty("Content-Type","application/octet-stream");connection.setFixedLengthStreamingMode(size);final String display=name;try(InputStream in=cached==null?getContentResolver().openInputStream(uri):new FileInputStream(cached);OutputStream out=connection.getOutputStream()){long sent=copy(in,out,size,display);if(sent!=size)throw new Exception("File changed while sending.");}JSONObject result=api.response(connection);if(!Arrays.asList("Received","Sent to qBittorrent").contains(result.optString("status")))throw new Exception(result.optString("message",result.optString("status")));}finally{if(connection!=null){connection.disconnect();connection=null;}if(cached!=null)cached.delete();}}
 private long copy(InputStream in,OutputStream out,long limit,String name)throws Exception{if(in==null)throw new Exception("File permission is unavailable. Choose the file again.");byte[] bytes=new byte[65536];long count=0;for(int n;(n=in.read(bytes))!=-1;){if(stopped||Thread.currentThread().isInterrupted())throw new InterruptedException();count+=n;if(count>limit)throw new Exception("File exceeds its size limit.");out.write(bytes,0,n);if(name!=null)progress(name+" · "+(limit==0?100:count*100/limit)+"%");}return count;}
 @Override public void onDestroy(){destroyed=true;stopped=true;running=false;inbox.clear();if(worker!=null)worker.interrupt();if(connection!=null)connection.disconnect();super.onDestroy();}@Override public IBinder onBind(Intent i){return null;}
}
